def match_parens(lst):
    if len(lst) != 2 or not all(isinstance(s, str) for s in lst):
        return 'No'

    for s in lst:
        if not all(c in ['(', ')'] for c in s):
            return 'No'

    open_count = 0
    for s in lst:
        for c in s:
            if c == '(':
                open_count += 1
            else:
                if open_count == 0:
                    return 'No'
                open_count -= 1

    return 'Yes'
